selected=set(sys.argv[1:])
for identifier,path,before,after in mutations:
 if selected and identifier not in selected:continue
 original=path.read_bytes();text=original.decode();count=text.count(before)
 if not count:raise RuntimeError(f'{identifier}: mutation text absent: {before}')
 # Only one behavioural site per mutation (same literal may occur in sibling paths).
 changed=text.replace(before,after,1).encode();line=text[:text.index(before)].count('\n')+1
 backup=pathlib.Path(tempfile.mktemp(prefix='t23b-mutation-'));backup.write_bytes(original)
 try:
  path.write_bytes(changed)
  pattern='^Test23_'+identifier.replace('-','_')+'_'
  result=subprocess.run([os.environ.get('GO', 'go'),'test','./internal/relay/sync','-run',pattern,'-count=1'],cwd=root,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,env=os.environ.copy())
  log=pathlib.Path(tempfile.gettempdir())/('t23b-mutation-'+identifier+'.log');log.write_bytes(result.stdout)
  if result.returncode==0 or b'[build failed]' in result.stdout:raise RuntimeError(f'{identifier}: invalid mutation result {result.returncode}: {result.stdout[-1000:]!r}')
  lines=result.stdout.decode(errors='replace').splitlines();first=next((x.strip() for x in lines if 'call ' in x or 'args=' in x or 'differs' in x or 'differ' in x),'comparison failure; see '+str(log))
  with evidence.open('a') as f:f.write(f'part B mutation {identifier}: {path.relative_to(root)}:{line}; before={before!r}; after={after!r}; exit={result.returncode}; first difference={first}; log={log}\n')
  print(identifier,'killed',flush=True)
 finally:
  shutil.copyfile(backup,path)
  subprocess.run(['cmp',str(backup),str(path)],check=True)
  backup.unlink()
